import { ok, fail } from './result.js';
import { roundCents } from './money.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Validate discount percent value.
 * @param {any} discountPercent
 * @returns {boolean}
 */
function isValidDiscount(discountPercent) {
  return discountPercent != null && typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Calculate due date based on payment terms.
 * @param {string} issueDate - YYYY-MM-DD format
 * @param {string} terms - 'NET14', 'NET30', or 'EOM'
 * @returns {string} due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    // Get the last day of the month of issueDate
    const [year, month] = issueDate.split('-');
    const nextMonth = parseInt(month) + 1;
    const yearForNextMonth = nextMonth === 13 ? parseInt(year) + 1 : year;
    const monthForNextMonth = nextMonth === 13 ? '01' : String(nextMonth).padStart(2, '0');
    const firstOfNextMonth = `${yearForNextMonth}-${monthForNextMonth}-01`;
    // Last day of current month is one day before first of next month
    return addDays(firstOfNextMonth, -1);
  }
}

/**
 * Validate payment terms.
 * @param {any} terms
 * @returns {boolean}
 */
function isValidTerms(terms) {
  return terms === 'NET14' || terms === 'NET30' || terms === 'EOM';
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize and validate customer
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  // Validate date
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate terms
  if (!isValidTerms(terms)) {
    return fail('TERMS_INVALID');
  }

  // Validate lines array is not empty
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Validate and build each line
  const invoiceLines = [];
  const customer = customerResult.value;
  for (const line of lines) {
    // Validate quantity
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Determine discount percent: explicit value always wins, otherwise use tier discount
    let discountPercent;
    if (Object.prototype.hasOwnProperty.call(line, 'discountPercent')) {
      // Line has explicit discountPercent
      if (!isValidDiscount(line.discountPercent)) {
        return fail('DISCOUNT_INVALID');
      }
      discountPercent = line.discountPercent;
    } else {
      // Use tier discount
      discountPercent = TIER_DISCOUNTS[customer.tier] ?? 0;
    }

    // Validate SKU exists and get product details
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  const dueDate = calculateDueDate(issueDate, terms);

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
    terms,
    dueDate,
  });
}

/**
 * Calculate the total amount for a single line item.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} total in cents
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate the discount amount for a single line item.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number} discount in cents, clamped at 0
 */
export function lineDiscount(line) {
  const discountPercent = line.discountPercent ?? 0;
  const total = lineTotal(line);
  const discount = roundCents((total * discountPercent) / 100);
  return Math.max(0, discount);
}

/**
 * Calculate the VAT amount for a single line item.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number} VAT in cents, clamped at 0
 */
export function lineVAT(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const taxableAmount = Math.max(0, total - discount);
  const vat = roundCents((taxableAmount * line.vatRate) / 100);
  return Math.max(0, vat);
}

/**
 * Calculate subtotal, discount, VAT, voucher, and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }} amounts in cents
 */
export function invoiceTotals(invoice) {
  const subtotal = roundCents(invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0));
  const discount = roundCents(invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0));
  const vat = roundCents(invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0));
  const voucher = invoice.voucher ? invoice.voucher.amount : 0;
  const total = Math.max(0, roundCents(subtotal - discount + vat - voucher));
  return {
    subtotal,
    discount,
    vat,
    voucher,
    total,
  };
}

/**
 * Add or update a line on an invoice.
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Validate invoice is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Validate quantity
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Determine discount percent: explicit value always wins, otherwise use tier discount
  let discount;
  if (Object.prototype.hasOwnProperty.call(arguments[1], 'discountPercent')) {
    // Explicit discountPercent provided
    if (!isValidDiscount(discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }
    discount = discountPercent;
  } else {
    // Use tier discount (customerId is already normalized in invoice)
    const customerResult = getCustomer(invoice.customerId);
    if (!customerResult.ok) return customerResult;
    const customer = customerResult.value;
    discount = TIER_DISCOUNTS[customer.tier] ?? 0;
  }

  // Validate SKU exists and get product details
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Find existing line with this SKU
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    // Update existing line
    newLines[existingLineIndex].qty += qty;
    if (Object.prototype.hasOwnProperty.call(arguments[1], 'discountPercent')) {
      newLines[existingLineIndex].discountPercent = discountPercent;
    }
  } else {
    // Add new line
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discount,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Validate invoice is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Find the line to remove
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if removing would leave no lines
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines
    .slice(0, lineIndex)
    .concat(invoice.lines.slice(lineIndex + 1))
    .map((line) => ({ ...line }));

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue an invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string }} invoice
 * @param {Array<string>} existingNumbers - invoice numbers already issued
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Validate invoice is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

