test('applyVoucher adds voucher to draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(invoice.ok, true);

  const r = applyVoucher(invoice.value, { code: 'SUMMER20', amount: 1000 });

  assert.equal(r.ok, true);
  assert.equal(r.value.voucher.code, 'SUMMER20');
  assert.equal(r.value.voucher.amount, 1000);
});

test('applyVoucher includes voucher in invoiceTotals', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(invoice.ok, true);

  const r = applyVoucher(invoice.value, { code: 'SUMMER20', amount: 1000 });
  assert.equal(r.ok, true);

  const totals = invoiceTotals(r.value);
  assert.equal(totals.voucher, 1000);
  const expectedTotal = totals.subtotal - totals.discount + totals.vat - 1000;
  assert.equal(totals.total, Math.max(0, expectedTotal));
});

test('applyVoucher reduces total correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(invoice.ok, true);

  const totalsWithoutVoucher = invoiceTotals(invoice.value);
  const voucherAmount = 5000;

  const r = applyVoucher(invoice.value, { code: 'DISCOUNT', amount: voucherAmount });
