test('applyVoucher clamps total to 0 if voucher exceeds amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);

  const totalsWithoutVoucher = invoiceTotals(invoice.value);
