    customerId: 'C-001',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });
  assert.equal(r1.value.dueDate, '2026-01-31');

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-12-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });
  assert.equal(r2.value.dueDate, '2026-12-31');
});

test('invoiceTotals includes voucher field', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
});

test('applyVoucher adds voucher to draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(invoice.ok, true);

  const r = applyVoucher(invoice.value, { code: 'SUMMER20', amount: 1000 });

  assert.equal(r.ok, true);
  assert.equal(r.value.voucher.code, 'SUMMER20');
  assert.equal(r.value.voucher.amount, 1000);
});

test('applyVoucher includes voucher in invoiceTotals', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(invoice.ok, true);

  const r = applyVoucher(invoice.value, { code: 'SUMMER20', amount: 1000 });
  assert.equal(r.ok, true);

  const totals = invoiceTotals(r.value);
  assert.equal(totals.voucher, 1000);
  const expectedTotal = totals.subtotal - totals.discount + totals.vat - 1000;
  assert.equal(totals.total, Math.max(0, expectedTotal));
});

test('applyVoucher reduces total correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(invoice.ok, true);

  const totalsWithoutVoucher = invoiceTotals(invoice.value);
  const voucherAmount = 5000;

  const r = applyVoucher(invoice.value, { code: 'DISCOUNT', amount: voucherAmount });
  assert.equal(r.ok, true);

  const totalsWithVoucher = invoiceTotals(r.value);
  assert.equal(totalsWithVoucher.total, totalsWithoutVoucher.total - voucherAmount);
});

test('applyVoucher rejects non-integer amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(invoice.ok, true);

  const r = applyVoucher(invoice.value, { code: 'BAD', amount: 1000.50 });

  assert.equal(r.ok, false);
  assert.equal(r.error, 'AMOUNT_INVALID');
});

test('applyVoucher rejects zero amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(invoice.ok, true);

  const r = applyVoucher(invoice.value, { code: 'ZERO', amount: 0 });

  assert.equal(r.ok, false);
  assert.equal(r.error, 'AMOUNT_INVALID');
});

test('applyVoucher rejects negative amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(invoice.ok, true);

  const r = applyVoucher(invoice.value, { code: 'NEG', amount: -1000 });

  assert.equal(r.ok, false);
  assert.equal(r.error, 'AMOUNT_INVALID');
});

test('applyVoucher rejects when voucher already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(invoice.ok, true);

  const r1 = applyVoucher(invoice.value, { code: 'FIRST', amount: 1000 });
  assert.equal(r1.ok, true);

  const r2 = applyVoucher(r1.value, { code: 'SECOND', amount: 2000 });

  assert.equal(r2.ok, false);
  assert.equal(r2.error, 'VOUCHER_EXISTS');
});

test('applyVoucher rejects on issued invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(invoice.ok, true);

  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);

  const r = applyVoucher(issued.value, { code: 'LATE', amount: 1000 });

  assert.equal(r.ok, false);
  assert.equal(r.error, 'NOT_DRAFT');
});

test('applyVoucher clamps total to 0 if voucher exceeds amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);

  const totalsWithoutVoucher = invoiceTotals(invoice.value);
  const voucherAmount = totalsWithoutVoucher.total + 10000; // Voucher larger than total

  const r = applyVoucher(invoice.value, { code: 'HUGE', amount: voucherAmount });
  assert.equal(r.ok, true);

  const totalsWithVoucher = invoiceTotals(r.value);
  assert.equal(totalsWithVoucher.total, 0);
});

test('applyVoucher does not mutate original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(invoice.ok, true);

  const originalVoucher = invoice.value.voucher;

  const r = applyVoucher(invoice.value, { code: 'TEST', amount: 1000 });

  assert.equal(r.ok, true);
  assert.equal(invoice.value.voucher, originalVoucher);
});

test('invoiceTotals with discount and voucher', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
    voucher: { code: 'SAVE', amount: 2000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 10000);
  assert.equal(totals.vat, Math.round((90000 * 21) / 100));
  assert.equal(totals.voucher, 2000);
  const expectedTotal = 100000 - 10000 + totals.vat - 2000;
  assert.equal(totals.total, expectedTotal);
});

test('invoiceTotals with multiple lines and voucher', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 5, unitPrice: 2000, discountPercent: 0, vatRate: 21 },
    ],
    voucher: { code: 'PROMO', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.voucher, 5000);
  const expectedVAT = Math.round((9000 * 21) / 100) + Math.round((10000 * 21) / 100);
  assert.equal(totals.vat, expectedVAT);
  const expectedTotal = 20000 - 1000 + expectedVAT - 5000;
  assert.equal(totals.total, expectedTotal);
});

